  ],
  "verdict": "BLOCKED",
  "checks": [
    {
      "id": "DECISION-JUSTIFIED",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Architecture and normative execution sections explain thin adapters, provider-owned state, conservative serialization, exact AWS Change Set execution and Azure preview refresh in terms of ownership, authorization and drift risks."
    },
    {
      "id": "OPEN-QUESTIONS-RESOLVABLE",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md OQ-001 and OQ-002 identify role owners, implementation blocking status and concrete resolution actions. Advisory: label those actions explicitly as Resolution Path: for template conformity."
    },
    {
      "id": "ASSUMPTIONS-VALID",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Assumptions adopts the GitHub Actions boundary already specified in requirements.md Assumptions and treats protected environments and exclusive write ownership as external prerequisites, not established facts."
    },
    {
      "id": "NO-REQ-CONTRADICTION",
      "result": "FAIL",
      "severity": "Critical",
      "finding": "requirements.md Security Boundaries requires region/account allowlists and configured evidence residency/retention. design.md Constraint Compliance contains only six rows and no compliance statement for these constraints. infra-spec.md Data Residency and Retention provides relevant controls, but the required compliance section does not map them. Complete that mapping so target-policy constraints cannot disappear from implementation compliance review; this omission is Critical under this check's explicit rule."
    },
    {
      "id": "PERF-ADDRESSED",
      "result": "PASS",
      "severity": "Minor",
      "finding": "No performance requirements found in requirements.md."
    },
    {
      "id": "DEPLOYMENT-CONCRETE",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Deployment / CI Plan specifies packaged plugins, reviewable workflow/IAM templates, credential-free deterministic CI and opt-in protected sandbox jobs. infra-spec.md CI/CD Sequence defines execution order and environments. No database schema migration or incremental production rollout is proposed."
    },
    {
      "id": "MIGRATION-PLANNED",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Data Plan introduces file-based contracts rather than database table/column changes. Its explicit version/profile dispatch preserves existing verification consumers and historical evidence; database migration requirements do not apply."
    },
    {
      "id": "INTEGRATION-IDENTIFIED",
      "result": "FAIL",
      "severity": "Major",
      "finding": "design.md Components identifies Azure CLI, AWS CLI/CDK and GitHub Actions, while authorization requires a trusted CI API to obtain approval metadata. No dedicated integration inventory specifies the supported provider CLI/API contracts or the CI approval API contract. The dependency-lock schema says tool versions will be recorded but does not select supported contracts. Implementers could choose incompatible approval metadata or preview formats at the write boundary. Add each integration's purpose, supported contract/version and unavailable/incompatible behavior; this ambiguity is blocking."
    },
    {
      "id": "DESIGN-WITHIN-SCOPE",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md covers REQ-001–012 through audit repair, routing, two thin adapters, immutable authorization, operation reconciliation, verification and bootstrap compatibility. infra-spec.md supplies both minimal examples and brownfield controls. No GUI, universal deployment engine or production rollout is introduced."
    },
    {
      "id": "VERIFICATION-PATH-CONCRETE",
      "result": "PASS",
      "severity": "Minor",
      "finding": "design.md Test Strategy binds TEST-001–012, including authorization denial, artifact mutation, replay, timeout, unhealthy resources, dependent-unit failure and no-change behavior. security-spec.md Security Tests maps security surfaces to concrete test IDs and evidence. Round 1: no prior summary used for remediation assessment."
    },
    {
      "id": "DOMAIN-CONFORMANCE",
      "result": "SKIP",
      "severity": "Minor",
      "finding": "SKIP: no domain/ directory, as supplied by the host and corroborated by investigation.md."
    }
  ]
}
